python3 << 'EOF'
import json
import subprocess

tests = [
    {
        "name": "Example 1: Basic call with parameters",
        "input": {
            "defs": {
                "Normalize": { "steps":[
                    {"op":"map","as":"z","expr":"(value - params.mean) / params.std"}
                ]},
                "KeepCols": { "steps":[
                    {"op":"select","columns":["id","z"]}
                ]}
            },
            "pipeline": {
                "steps": [
                    {"op":"call","name":"Normalize","params":{"mean":100,"std":20}},
                    {"op":"call","name":"KeepCols","params":{}}
                ]
            },
            "dataset":[
                {"id":1,"value":120},
                {"id":2,"value":80}
            ]
        },
        "expected": {
            "status":"ok",
            "data":[
                {"id":1,"z":1},
                {"id":2,"z":-1}
            ],
            "metrics":{"rows_in":2,"rows_out":2}
        }
    },
    {
        "name": "Example 2: Missing definition",
        "input": {
            "defs": {},
            "pipeline": { "steps": [ {"op":"call","name":"Missing","params":{}} ] },
            "dataset":[{"id":1}]
        },
        "expected": {
            "status":"error",
            "error_code":"UNKNOWN_DEF",
            "path":"pipeline.steps[0].name"
        }
    },
    {
        "name": "Example 3: Direct recursion",
        "input": {
            "defs": {
                "Loop": { "steps":[ {"op":"call","name":"Loop","params":{}} ] }
            },
            "pipeline": { "steps": [ {"op":"call","name":"Loop","params":{}} ] },
            "dataset":[{"id":1}]
        },
        "expected": {
            "status":"error",
            "error_code":"RECURSION_FORBIDDEN",
            "path":"defs[Loop].steps[0].name"
        }
    }
]

for test in tests:
    print(f"Testing: {test['name']}")
    result = subprocess.run(
        ["python3", "etl_pipeline.py", "--execute", "true"],
        input=json.dumps(test['input']),
        capture_output=True,
        text=True
    )
    output = json.loads(result.stdout)

    expected = test['expected']
    if output.get('status') == 'ok':
        data_match = output.get('data') == expected.get('data')
        metrics_match = output.get('metrics') == expected.get('metrics')
        if data_match and metrics_match:
            print("✓ PASS")
        else:
            print("✗ FAIL")
            print(f"  Expected: {json.dumps(expected)}")
            print(f"  Got:      {json.dumps(output)}")
    else:
        error_match = (
            output.get('error_code') == expected.get('error_code') and
            output.get('path') == expected.get('path')
        )
        if error_match:
            print("✓ PASS")
        else:
            print("✗ FAIL")
            print(f"  Expected error_code: {expected.get('error_code')}, path: {expected.get('path')}")
            print(f"  Got error_code:      {output.get('error_code')}, path: {output.get('path')}")
    print()

EOF

